SELECT AVG(n_correct) / n_decisions AS escalation_rate
FROM marts.fct_outcomes
WHERE is_correct = FALSE;

SELECT COUNT(*) AS escalations
FROM marts.fct_requests
WHERE is_escalated = TRUE;

SELECT COUNT(*) AS recent_tickets
FROM marts.dim_prompt_version
WHERE opened_at > NOW() - INTERVAL '1 week';

SELECT COUNT(request_id) AS failed_calls
FROM marts.fct_requests
WHERE http_status != 200;
